<template>
    <div class="tournament-list" :class="{ 'visible': visible }">
        <MenuBar 
            v-if="activeTournamentEntry || upcomingTournaments.length > 0"
            :active-tab="'leagues'" 
            :tournament-id="defaultTournamentId" 
            @change-panel="(panel, id) => $emit('change-panel', panel, id)" 
        />
        <div class="prize-rules">
            {{ translations.tournamentList.promo.line1 }}<br>{{ translations.tournamentList.promo.line2 }}
        </div>
        <div class="tournament-history-link">
            <div class="left">
                <div class="section-title">{{ translations.tournamentList.completedLeagues }}</div>
            </div>
            <div class="view-button pill-button" @click="onHistoryClicked">{{ translations.actions.view }}</div>
        </div>

        <div class="list-box">
            <div class="section" v-if="activeTournamentEntry">
                <div class="section-title">{{ translations.tournamentList.activeLeague }}</div>
                <div class="list-item">
                    <div class="tournament-dot"></div>
                    <div class="tournament-date">
                        {{ formatDate(activeTournamentEntry.startTimeObject) }}
                    </div>
                    <div class="opt-in-button pill-button" v-if="!activeTournamentEntry.hasOptedIn" @click="onOptInClicked(activeTournamentEntry.tournamentId)">{{ translations.actions.optIn }}</div>
                    <div class="view-button pill-button" v-if="activeTournamentEntry.hasOptedIn" @click="onViewClicked(activeTournamentEntry.tournamentId)">{{ translations.actions.view }}</div>
                </div>
            </div>

            <div class="section" v-if="upcomingTournaments.length > 0">
                <div class="section-title">{{ translations.tournamentList.upcomingLeagues }}</div>
                <div class="list-item" v-for="tournament in upcomingTournaments" :key="tournament.tournamentId">
                    <div class="tournament-dot"></div>
                    <div class="tournament-date">
                        {{ formatDate(tournament.startTimeObject) }}
                    </div>
                    <div class="opt-in-button pill-button" v-if="!tournament.hasOptedIn" @click="onOptInClicked(tournament.tournamentId)">{{ translations.actions.optIn }}</div>
                    <div class="view-button pill-button" v-if="tournament.hasOptedIn" @click="onViewClicked(tournament.tournamentId)">{{ translations.actions.view }}</div>
                </div>
            </div>
        </div>

        <div class="no-tournament-text" v-if="!activeTournamentEntry && upcomingTournaments.length === 0">{{ translations.tournamentList.noTournaments }}</div>
    </div>
</template>

<script src="./tournament-list.ts"   lang="ts"></script>
<style  src="./tournament-list.less" lang="less" scoped></style>